local MirrorMaker = {}
local PRODUCTS = {
    hand_mirror = { name = "Ročno zrcalo", glassCost = 1, woodCost = 1, tinCost = 1, time = 2, cost = 25, clarity = 50, description = "Ročno zrcalo za vsakdanjo rabo." },
    wall_mirror = { name = "Stensko zrcalo", glassCost = 2, woodCost = 2, tinCost = 1, time = 4, cost = 60, clarity = 60, prestige = 2, description = "Stensko zrcalo za dvorane." },
    silver_mirror = { name = "Srebrno zrcalo", glassCost = 2, woodCost = 1, silverCost = 1, time = 6, cost = 140, clarity = 75, prestige = 5, happiness = 1, description = "Srebrno zrcalo za plemiče." },
    silver_frame_mirror = { name = "Srebrno okvirno zrcalo", glassCost = 2, silverCost = 1, goldCost = 1, time = 9, cost = 320, clarity = 85, prestige = 10, happiness = 2, description = "Zrcalo v srebrnem okvirju za visoke plemiče." },
    gold_frame_mirror = { name = "Zlato okvirno zrcalo", glassCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, time = 12, cost = 700, clarity = 92, prestige = 18, happiness = 4, description = "Zrcalo v zlatem okvirju z draguljem." },
    royal_grand_mirror = { name = "Kraljevski veliki zrcalo", glassCost = 4, goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, time = 17, cost = 1800, clarity = 100, prestige = 40, happiness = 8, description = "Veliko kraljevsko zrcalo z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Zrcalna delavnica", cost = { gold = 280, wood = 130, stone = 250 }, upkeep = 7, qualityBonus = 5 },
    silvering_room = { name = "Srebrilnica", cost = { gold = 950, wood = 250, stone = 450, glass = 8 }, upkeep = 23, qualityBonus = 18 },
    polishing_room = { name = "Polirnica", cost = { gold = 2300, wood = 350, stone = 700, silver = 30, tin = 8 }, upkeep = 58, qualityBonus = 30 },
    royal_mirror_atelier = { name = "Kraljevski atelje zrcal", cost = { gold = 9000, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 40 },
}
MirrorMaker.glassStock = 14; MirrorMaker.woodStock = 14; MirrorMaker.tinStock = 12; MirrorMaker.silverStock = 8; MirrorMaker.goldStock = 6; MirrorMaker.jewelStock = 6; MirrorMaker.pearlStock = 4
MirrorMaker.productStock = {}; MirrorMaker.buildings = {}; MirrorMaker.maker = nil; MirrorMaker.activeMaking = {}; MirrorMaker.totalProducts = 0; MirrorMaker.dayTimer = 0
function MirrorMaker.init() MirrorMaker.glassStock=14; MirrorMaker.woodStock=14; MirrorMaker.tinStock=12; MirrorMaker.silverStock=8; MirrorMaker.goldStock=6; MirrorMaker.jewelStock=6; MirrorMaker.pearlStock=4; MirrorMaker.productStock={}; MirrorMaker.buildings={}; MirrorMaker.maker=nil; MirrorMaker.activeMaking={}; MirrorMaker.totalProducts=0; MirrorMaker.dayTimer=0; print("[MirrorMaker] Royal Mirror Maker System initialized (6 products, 4 buildings)") end
function MirrorMaker.hireMaker(n,s) s=s or math.random(50,90); local c=520+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MirrorMaker.maker={name=n or ("Zrcalar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zrcalar najet: %s (spretnost: %d)",MirrorMaker.maker.name,s),"success") end; return true end
function MirrorMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MirrorMaker.build(id) local ok,e=MirrorMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MirrorMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MirrorMaker.getQualityBonus() local b=0; for _,bd in ipairs(MirrorMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MirrorMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.glassCost and MirrorMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.woodCost and MirrorMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.tinCost and MirrorMaker.tinStock<(d.tinCost or 0) then return false,"Premalo kositra" end; if d.silverCost and MirrorMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MirrorMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MirrorMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MirrorMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MirrorMaker.buildings==0 then return false,"Potrebna delavnica" end; if not MirrorMaker.maker then return false,"Potreben zrcalar" end; return true end
function MirrorMaker.make(pt,qty) qty=qty or 1; local ok,e=MirrorMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.glassCost then MirrorMaker.glassStock=MirrorMaker.glassStock-d.glassCost*qty end; if d.woodCost then MirrorMaker.woodStock=MirrorMaker.woodStock-d.woodCost*qty end; if d.tinCost then MirrorMaker.tinStock=MirrorMaker.tinStock-d.tinCost*qty end; if d.silverCost then MirrorMaker.silverStock=MirrorMaker.silverStock-d.silverCost*qty end; if d.goldCost then MirrorMaker.goldStock=MirrorMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MirrorMaker.jewelStock=MirrorMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MirrorMaker.pearlStock=MirrorMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MirrorMaker.maker then t=math.max(1,t-math.floor(MirrorMaker.maker.skill/12)) end; table.insert(MirrorMaker.activeMaking,{id="mirror_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,clarity=d.clarity or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MirrorMaker.completeMaking(m) local q=1.0+(MirrorMaker.getQualityBonus()/100); if MirrorMaker.maker then q=q+(MirrorMaker.maker.skill/180) end; q=math.min(2.0,q); MirrorMaker.productStock[m.productType]=(MirrorMaker.productStock[m.productType] or 0)+m.quantity; MirrorMaker.totalProducts=MirrorMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MirrorMaker.maker then MirrorMaker.maker.itemsMade=MirrorMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then MirrorMaker.maker.skill=math.min(100,MirrorMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zrcalo izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"mirror.completed",{productName=m.productName,clarity=m.clarity,prestige=m.prestige,happiness=m.happiness}) end end
function MirrorMaker.update(dt) if not _G.state then return end; MirrorMaker.dayTimer=MirrorMaker.dayTimer+dt; if MirrorMaker.dayTimer>=30 then MirrorMaker.dayTimer=0; for i=#MirrorMaker.activeMaking,1,-1 do local m=MirrorMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MirrorMaker.completeMaking(m); table.remove(MirrorMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MirrorMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MirrorMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MirrorMaker.getStats() return {glassStock=MirrorMaker.glassStock,woodStock=MirrorMaker.woodStock,tinStock=MirrorMaker.tinStock,silverStock=MirrorMaker.silverStock,goldStock=MirrorMaker.goldStock,jewelStock=MirrorMaker.jewelStock,pearlStock=MirrorMaker.pearlStock,productStock=MirrorMaker.productStock,numBuildings=#MirrorMaker.buildings,hasMaker=MirrorMaker.maker~=nil,makerName=MirrorMaker.maker and MirrorMaker.maker.name or "—",makerSkill=MirrorMaker.maker and MirrorMaker.maker.skill or 0,activeMaking=#MirrorMaker.activeMaking,totalProducts=MirrorMaker.totalProducts} end
return MirrorMaker
